We compare character frequencies. A window of length equal to the pattern slides over the text; for each position we maintain a count of matches between the window's character frequencies and the pattern's. We use two dicts and increment or decrement a counter of matched character types as the window moves. When the match counter equals the number of distinct pattern characters we have found a permutation.

```python
from typing import Dict

def has_permutation(s: str, pattern: str) -> bool:
    """Return True if some substring of s is a permutation of pattern.

    Args:
        s: The text to search.
        pattern: The pattern string.

    Returns:
        True if any substring of s of length len(pattern) is an anagram of pattern.

    Examples:
        >>> has_permutation("oidbcaf", "abc")
        True
        >>> has_permutation("odicf", "dc")
        False
        >>> has_permutation("aaab", "ab")
        True
    """
    k = len(pattern)
    if k == 0 or k > len(s):
        return k == 0
    need: Dict[str, int] = {}
    have: Dict[str, int] = {}
    for ch in pattern:
        need[ch] = need.get(ch, 0) + 1
    for i in range(k):
        have[s[i]] = have.get(s[i], 0) + 1
    matches = sum(1 for ch in need if have.get(ch, 0) == need[ch])
    if matches == len(need):
        return True
    for i in range(k, len(s)):
        out, inn = s[i - k], s[i]
        if out in have:
            have[out] -= 1
            if have[out] == 0:
                del have[out]
        have[inn] = have.get(inn, 0) + 1
        if out in need:
            if have.get(out, 0) + 1 == need[out]:
                matches += 1
            elif have.get(out, 0) == 0 and out in have:
                matches -= 1
        if inn in need:
            if have[inn] == need[inn]:
                matches += 1
            elif have.get(inn, 0) - 1 == need[inn]:
                matches -= 1
        if matches == len(need):
            return True
    return False
```

We extend the minimum-window pattern with a per-character upper bound. Two dicts track the needed counts and the current counts, and a counter tracks how many distinct character types are fully satisfied. Additionally we track the maximum character count inside the window; if any character exceeds two we shrink from the left until it is back at most two. The smallest window meeting all three constraints is the answer.

```python
from typing import Dict

def min_window_with_cap(s: str, t: str, cap: int = 2) -> str:
    """Return the smallest substring of s containing all characters of t with per-character cap.

    Args:
        s: The text to search.
        t: The pattern with required character multiplicities.
        cap: The maximum allowed count of any character inside the window.

    Returns:
        The smallest qualifying window, or '' if none exists.

    Examples:
        >>> min_window_with_cap("ADOBECODEBANC", "ABC")
        'BANC'
        >>> min_window_with_cap("aaaaa", "aa")
        'aa'
        >>> min_window_with_cap("abc", "abcd")
        ''
    """
    if not t or len(t) > len(s):
        return ""
    need: Dict[str, int] = {}
    for ch in t:
        need[ch] = need.get(ch, 0) + 1
    have: Dict[str, int] = {}
    satisfied = 0
    required = len(need)
    best = (len(s) + 1, "")
    left = 0
    for right, ch in enumerate(s):
        if ch in need:
            have[ch] = have.get(ch, 0) + 1
            if have[ch] == need[ch]:
                satisfied += 1
        if have.get(ch, 0) > cap:
            while have.get(ch, 0) > cap:
                out = s[left]
                left += 1
                if out in need:
                    if have[out] == need[out]:
                        satisfied -= 1
                    have[out] -= 1
        while satisfied == required and have.get(ch, 0) <= cap:
            if right - left + 1 < best[0]:
                best = (right - left + 1, s[left:right + 1])
            out = s[left]
            left += 1
            if out in need:
                if have[out] == need[out]:
                    satisfied -= 1
                have[out] -= 1
    return best[1]
